                py = int(curr_img.height * y_frac)
                if curr_img.getpixel((px, py)) != prev_img.getpixel((px, py)):
                    is_dup = False
                    break
            if not is_dup:
                break

        if not is_dup:
            unique.append(png)
            prev_img = curr_img
